/bin/zsh -lc "python3 - <<'PY'
import urllib.request,urllib.parse,re,html
for engine in ['https://html.duckduckgo.com/html/?q=','https://www.bing.com/search?q=']:
 try:
  q='Figma keyboard shortcut create instance component'
  req=urllib.request.Request(engine+urllib.parse.quote(q),headers={'User-Agent':'Mozilla/5.0'})
  s=urllib.request.urlopen(req,timeout=15).read().decode('utf-8','ignore')
  print(engine,len(s))
  s=re.sub(r'<script.*?</script>|<style.*?</style>',' ',s,flags=re.S|re.I)
  t=html.unescape(re.sub(r'<["'^>]+>'"','\\n',s))
  lines=[re.sub(r'\\s+',' ',x).strip() for x in t.splitlines()]
  for x in lines:
   if x and re.search(r'instance|shortcut|component',x,re.I): print(x[:400])
  break
 except Exception as e: print(engine,e)
PY"

